def lexical_entries(language):
    places = {"crosby_richard_house", "chertsey_henry_burial", "baynard_richard_castle", "bosworth_battlefield",
              "ludlow_princes_residence", "stony_stratford_road", "northampton_princes_road", "holborn_ely_garden",
              "exeter_rougemont_city", "rougemont_exeter_castle", "brecknock_buckingham_refuge",
              "devonshire_rising_county", "dorsetshire_landing_coast", "pembroke_welsh_place",
              "harfordwest_welsh_place", "tamworth_richmond_march"}
    return build_entries(language, NAMES, SENSES, places)


def prepare():
    add_source_entries("richard-iii", "richard-ii", lexical_entries,
        "Reuse the named Yorkist family across the histories. Distinguish the two princes from their father, uncle and the Lancastrian prince, and retain the Roman spelling in the prophecy without changing the localized names.")


if __name__ == "__main__":
    prepare()
